<form class="filters" method="get"><input type="hidden" name="ruta" value="escuelas"><label>Buscar<input name="busqueda" value="<?= escapar($busqueda) ?>" placeholder="CCT, nombre, municipio o localidad"></label><label>Servicio Regional<select name="servicio_id"><option value="0">Todos</option><?php foreach($servicios as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $servicioId===(int)$s['id']?'selected':'' ?>><?= escapar($s['nombre']) ?></option><?php endforeach; ?></select></label><button class="button">Buscar</button></form>
<div class="table-wrap"><table><thead><tr><th>CCT</th><th>Escuela</th><th>Nivel</th><th>Municipio</th><th>Localidad</th><th>Servicio Regional</th><th>CCT Ser. Regional</th><th>Solicitudes</th><th>Última solicitud</th><th>Proceso de almacén</th></tr></thead><tbody><?php if(!$escuelas): ?><tr><td colspan="10" class="empty">Sin registros.</td></tr><?php endif; foreach($escuelas as $e): ?><tr><td><?= escapar($e['cct']) ?></td><td><strong><?= escapar($e['nombre']) ?></strong></td><td><?= escapar($e['nivel']??'') ?></td><td><?= escapar($e['municipio']??'') ?></td><td><?= escapar($e['localidad']??'') ?></td><td><?= escapar($e['servicio_regional']??'Sin relación vigente') ?></td><td><?= escapar($e['cct_servicio_regional']??'—') ?></td><td><?= numero($e['solicitudes']) ?></td><td><?= escapar($e['ultima_solicitud']??'—') ?></td><td><span class="status"><?= escapar(str_replace('_',' ',$e['estado_proceso'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div>
